// src/components/ShortsSection.js
import React, { useState, useEffect } from 'react';
import ReactPlayer from 'react-player';
import './ShortsSection.css';

const videoData = [
  { id: 1, url: 'https://www.example.com/video1.mp4', title: 'Short 1' },
  { id: 2, url: 'https://www.example.com/video2.mp4', title: 'Short 2' },
  { id: 3, url: 'https://www.example.com/video3.mp4', title: 'Short 3' },
];

const ShortsSection = () => {
  const [currentVideoIndex, setCurrentVideoIndex] = useState(0);

  const handleScroll = (event) => {
    const { scrollTop, clientHeight } = event.target;
    const newIndex = Math.round(scrollTop / clientHeight);
    setCurrentVideoIndex(newIndex);
  };

  return (
    <div className="shorts-container" onScroll={handleScroll}>
      {videoData.map((video, index) => (
        <div
          key={video.id}
          className={`short-video ${index === currentVideoIndex ? 'active' : ''}`}
        >
          <ReactPlayer
            url={video.url}
            playing={index === currentVideoIndex}
            controls={false}
            width="100%"
            height="100%"
          />
          <div className="video-title">{video.title}</div>
        </div>
      ))}
    </div>
  );
};

export default ShortsSection;
